const r = await tools.exec_command({cmd:"python - <<'PY'
from rcb_client import Robot
import numpy as np
from PIL import Image
from scipy import ndimage as ndi
r=Robot();p=np.asarray(r.get_obs(video='none').meta['proprio']['now'],float)[7:14];cur=p[:3];ori=np.array([0.,1.,0.,0.]);pts=[]
for w in [np.array([cur[0],cur[1],.30]),np.array([-.10,.25,.30])]:
 n=max(1,int(np.ceil(np.linalg.norm(w-cur)/.006)))
 for t in np.linspace(1/n,1,n):pts.append(cur+(w-cur)*t)
 cur=w
res=r.submit('ee_pose',np.array([[*x,*ori] for x in pts],np.float32),dt=.05,cameras=['canvas_cam','scene_cam','side_cam'],video='mp4',video_fps=10,note='clear paper for final visual inspection')
print('tip',res.meta['proprio']['now'][7:10],'IKfail',sum(a.get('ik_failures',0) for a in res.meta['plan']),'time_left',res.meta.get('time_left_s'))
res.save('/app/runs/final_clear')
o=r.get_obs(cameras=['canvas_cam','scene_cam','side_cam'],depth=True,video='none')
for k,v in o.last.items():Image.fromarray(v).save('/app/output/final_'+k+'.png')
im=np.asarray(o.last['canvas_cam']); actual=Image.fromarray((im[68:956,68:956,0]<80).astype('uint8')*255).resize((1024,1024),Image.Resampling.NEAREST); a=np.asarray(actual)>0; t=np.asarray(Image.open('/app/target.png').convert('L'))<128
inter=np.logical_and(a,t).sum(); print('thresholded coverage',inter/t.sum(),'precision',inter/a.sum(),'IoU',inter/np.logical_or(a,t).sum(),'actual_pixels',a.sum(),'target_pixels',t.sum())
lab,n=ndi.label(t,structure=np.ones((3,3)))
for i in range(1,n+1):
 c=lab==i;print('comp',i,'coverage',round(np.logical_and(c,a).sum()/c.sum(),3))
print('status',r.status())
PY",workdir:"/app",yield_time_ms:30000,max_output_tokens:500});
